<section class="page-banner"><div class="container"><a class="back-link" href="<?= e(url('leader',['club_id'=>$club['id']])) ?>">← Club studio</a><div class="section-label">MEMBERSHIP DIRECTORY</div><h1><?= e($club['name']) ?> · Members</h1><p>Approve incoming requests and review club membership records.</p></div></section><section class="section container"><div class="card panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Student</th><th>Student number</th><th>Email</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($members as $m): ?><tr><td><strong><?= e($m['full_name']) ?></strong><br><small><?= e($m['faculty']) ?></small></td><td><?= e($m['student_number']) ?></td><td><?= e($m['email']) ?></td><td><?= status_pill($m['status']) ?></td><td><?php if($m['status']==='pending'): ?><div class="row-actions"><?php foreach(['approved'=>'Approve','rejected'=>'Reject'] as $status=>$label): ?><form method="post" action="<?= e(url('leader/membership')) ?>"><?= csrf_field() ?><input type="hidden" name="club_id" value="<?= (int)$club['id'] ?>"><input type="hidden" name="membership_id" value="<?= (int)$m['id'] ?>"><button type="submit" name="status" value="<?= e($status) ?>" class="btn btn-outline btn-sm"><?= e($label) ?></button></form><?php endforeach; ?></div><?php elseif($m['status']==='approved' && user()['role']==='admin'): ?><form method="post" action="<?= e(url('admin/member/remove')) ?>" data-confirm="Remove this member from the club?"><?= csrf_field() ?><input type="hidden" name="club_id" value="<?= (int)$club['id'] ?>"><input type="hidden" name="membership_id" value="<?= (int)$m['id'] ?>"><button class="btn btn-outline btn-sm" type="submit">Remove member</button></form><?php else: ?><span class="small-muted">—</span><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$members): ?><tr><td colspan="5">No membership records yet.</td></tr><?php endif; ?></tbody></table></div></div></section>
